import axios from "axios";
import { useEffect } from "react";

export default function getMLABDATA(country, year, group, table){
    useEffect(()=>{
        console.log('called function to get Data')
    const data = async()=>{
        if (country != "all"){
            const response = await fetchData("https://mlab-13prsouz.uc.gateway.dev/"+table+
                "?country="+country+"&year="+year+"group_by="+group);
            return response;
            
        }else{
            const response = await fetchData("https://mlab-13prsouz.uc.gateway.dev/compute?country="
                +country+"&year="+year+"group_by="+group);
        console.log('data response');
        console.log(response);
            return response;
        }
        
          
    }

    const fetchData=async(command)=>{
        const dataResponse = await axios.post(command);
        
        return dataResponse.data;
    };
    })
    

    return data;

}
